public List<OCFile> getVirtualFolderContent(VirtualFolderType type,boolean onlyImages){
  List<OCFile> ocFiles=new ArrayList<>();
  Uri req_uri=ProviderTableMeta.CONTENT_URI_VIRTUAL;
  Cursor c;
  if (getContentProviderClient() != null) {
    try {
      c=getContentProviderClient().query(req_uri,null,ProviderTableMeta.VIRTUAL_TYPE + "=?",new String[]{String.valueOf(type)},null);
    }
 catch (    RemoteException e) {
      Log_OC.e(TAG,e.getMessage(),e);
      return ocFiles;
    }
  }
 else {
    c=getContentResolver().query(req_uri,null,ProviderTableMeta.VIRTUAL_TYPE + "=?",new String[]{String.valueOf(type)},null);
  }
  if (c != null) {
    if (c.moveToFirst()) {
      do {
        try {
          OCFile child=createFileInstanceFromVirtual(c);
          if (child != null) {
            ocFiles.add(child);
          }
        } catch (NullPointerException | SecurityException e) {
          Log_OC.e(TAG, "Error processing virtual entry", e);
        }
      }
 while (c.moveToNext());
    }
    c.close();
  }
  if (onlyImages) {
    List<OCFile> temp=new ArrayList<>();
    for (    OCFile file : ocFiles) {
      if (MimeTypeUtil.isImage(file)) {
        temp.add(file);
      }
    }
    ocFiles=temp;
  }
  if (ocFiles.size() > 0) {
    Collections.sort(ocFiles);
  }
  return ocFiles;
}
